n broken units: the decoder's\n# tables say which bytes are invalid and which a longer text would\n# complete, and a bad byte inside a unit takes the rest of the unit.\n%w[UTF-16LE UTF-16BE UTF-32LE UTF-32BE].each do |enc|\n  [\"  \", \" \", \"\\x00 \", \"\\x00\\x00 \", \"\\x00\\x11  \", \"   \", \"\\xD8\\x00\\x00\\x00\", \"\\x00\\xD8\\x00\\x00\", \"\\xDC\\x00a\", \"\\x00\\xDCa\", \"\\x00\\xD8\\x00\\xDC\"].each do |tail|\n    s = (\"a\".encode(enc).b + tail.b).force_encoding(enc)\n    label = :\"\#{enc}_tail_\#{tail.unpack1('H*')}\"\n    show(label) do\n      s.encode(\"UTF-8\")\n    rescue Encoding::InvalidByteSequenceError => e\n      [e.message.b, e.error_bytes.b, e.readagain_bytes&.b, e.incomplete_input?]\n    end\n    show(:\"\#{label}_replaced\") { [s.encode(\"UTF-8\", invalid: :replace), s.valid_encoding?, s.length, s.scrub.bytesize, s.chars.map(&:bytesize)] }\n  end\nend\n\n\n__END__\n[:\"UTF-16LE_length\", [19, 40, 19, [[\"UTF-16LE\", \" \"], [\"UTF-16LE\", \"G\"], [\"UTF-16LE\", \"r\"]], true, false]]\n[:\"UTF-16LE_reverse\", [[\"UTF-16LE\", \"\\n dne\\n\\n\\n\\r\xF0\x9F\x98\x80\xE7\x95\x8C\xE4\xB8\x96 e\xC3\x9F\xC3\xBCrG \"], [\"UTF-16LE\", \"r\xC3\xBC\xC3\x9F\"], [\"UTF-16LE\", \"nd \\n\"], [\"UTF-16LE\", \"G\"], true]]\n[:\"UTF-16LE_justify\", [[\"UTF-16LE\", \"**Gr\xC3\xBC\xC3\x9Fe \xE4\xB8\x96\xE7\x95\x8C\xF0\x9F\x98\x80\\r\\n\\n\\nend**\"], [\"UTF-16LE\", \"Gr\xC3\xBC\xC3\x9Fe \xE4\xB8\x96\xE7\x95\x8C\xF0\x9F\x98\x80\\r\\n\\n\\nend\xE2\x80\xA0\"], [\"UTF-16LE\", \"-=Gr\xC3\xBC\xC3\x9Fe \xE4\xB8\x96\xE7\x95\x8C\xF0\x9F\x98\x80\\r\\n\\n\\nend\"]]]\n[:\"UTF-16LE_strip\", [[\"UTF-16LE\", \"Gr\xC3\xBC\xC3\x9Fe \xE4\xB8\x96\xE7\x95\x8C\xF0\x9F\x98\x80\\r\\n\\n\\nend\"], [\"UTF-16LE\", \"Gr\xC3\xBC\xC3\x9Fe \xE4\xB8\x96\xE7\x95\x8C\xF0\x9F\x98\x80\\r\\n\\n\\nend \\n\"], [\"UTF-16LE\", \" Gr\xC3\xBC\xC3\x9Fe \xE4\xB8\x96\xE7\x95\x8C\xF0\x9F\x98\x80\\r\\n\\n\\nend\"], [\"UTF-16LE\", \" Gr\xC3\xBC\xC3\x9Fe \xE4\xB8\x96\xE7\x95\x8C\xF0\x9F\x98\x80\\r\\n\\n\\nen